export function InlineValidation({
  label = "{{label}}",
  value = "{{value}}",
  message = "{{message}}",
  valid = {{valid}},
  accent = "{{accent}}",
}) {
  return (
    <div style={{ fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", maxWidth: 260 }}>
      <label htmlFor="iv-react-1" style={{ display: "block", marginBottom: 6, fontWeight: 500 }}>{label}</label>
      <div style={{ position: "relative" }}>
        <input id="iv-react-1" type="text" defaultValue={value} aria-invalid={!valid} aria-describedby="iv-react-msg-1" style={{
          width: "100%", boxSizing: "border-box", padding: "10px 34px 10px 12px", font: "inherit", color: "#241430",
          background: "#FAF7F2", border: `1.5px solid ${accent}`, borderRadius: 8,
        }} />
        <span aria-hidden="true" style={{ position: "absolute", right: 10, top: "50%", transform: "translateY(-50%)", color: accent, fontWeight: 700 }}>
          {valid ? "✓" : "✗"}
        </span>
      </div>
      <p id="iv-react-msg-1" style={{ margin: "6px 0 0", fontSize: 12, color: accent }}>{message}</p>
    </div>
  );
}
